#!/usr/bin/env bash
# Generates owner-review reference images for one kit piece or family with Higgsfield nano_banana_pro (R2).
# Usage: scripts/refs/higgsfield-refs.sh <id>
#   P1 pieces: meadow_base road_straight tree_hero_oak
#   P2 MVP families: road_bends river river_road_bridge beach ocean house_cluster forest meadow_props
#   P2 agents: vehicles (sedan, van, pickup), fish, birds
#   P3 families: rail rail_station train farm farm_animals windmill bakery
#   River ends (owner 2026-10-14): river_mouth river_spring
#   Rail line ends: rail_buffer_stop
#   Beach dressing (2026-10-20): driftwood dune_grass
#   Boats (P3 agents) and the lighthouse (P6): boat_rowing boat_sail lighthouse
#   Village well (2026-10-20): well_stone
set -euo pipefail
id="$1"; out="assets-source/refs/$id"; mkdir -p "$out"
style="stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun, neutral grey studio background, 35 degree three-quarter view"
# Owner-approved looks carried into the P2 families: meadow_base ref-1 strata, road_straight ref-1, docs/checkpoints/water.
strata="layered soil strata on the hexagon side walls (dark topsoil, red clay, gravel)"
road="6 m wide two-lane asphalt country road, faded dashed white centre line, low concrete kerbs, grass verges with tufts and small bushes"
water="clear water tinted pale turquoise in the shallows and deep teal-blue where deep, sun glints, soft caustics on the shallow bed"
cut="the hexagon side wall shows the water column in cross-section like clear tinted resin, turquoise at the top fading to deep blue at the bottom, never an empty gap"
topstyle="stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun, neutral grey studio background, high camera looking down at about 65 degrees elevation so all six hexagon edges read clearly, soil strata visible on the front side walls"
# Vehicles are recoloured per instance at runtime (PRD §6), so the reference paint is a plain neutral base.
car="the whole body painted one plain neutral light grey satin paint with no stripes, decals or two-tone, clearly separate dark-tinted window glass, black rubber tyres on simple silver-grey wheels, satin chrome and dark grey trim on the bumpers, grille, window surrounds and door handles, clear headlights at the front and red taillights wrapping around the rear corners, plain unbadged bodywork with no logos, emblems or lettering anywhere, timeless modern-classic European styling with softly rounded edges and slightly chunky friendly proportions, realistic scale-model detail"
alone="standing alone on the plain grey studio floor with a soft contact shadow, the whole vehicle centred in frame, seen from the front-left"
# Fish and birds are GPU-instanced boids of about 100-200 triangles with vertex-animated swimming and flapping (PRD §7.2),
# so their references ask for simple smooth forms and flat colour blocks. Each slot names its own camera; frame-filling
# slots (the two overhead views) spell out $look without its studio background, which boxed the water in resin.
look="stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun, neutral grey studio background"
fishbody="a simple streamlined torpedo-shaped body with a smooth rounded head, a large dark eye, a clean forked tail fin, one small triangular dorsal fin and small rounded pectoral fins, every fin a solid smooth rounded shape, the scales reading as a soft satin sheen over broad smooth colour areas, smooth sculpted forms like a quality scale model with a bold readable silhouette"
oceanfish="a blue-grey back fading to bright silver sides and a white underside"
riverfish="an olive-brown back fading to golden-olive sides with a few faint dark spots, a pale cream underside and orange-red lower fins"
birdbody="small stylized songbird about the size of a starling with a compact rounded body, a round head, a short pointed dark beak, broad clearly shaped pointed wings with a smooth trailing edge and a short fan-shaped tail, in plain feather colour blocks: slate blue-grey back and upper wings, charcoal wingtips and tail tip, a warm rusty-orange breast and a pale cream underside, the feathers reading as broad smooth painted areas, smooth sculpted forms like a quality scale model with a bold readable silhouette"
# P3 tiles use the owner's O4 cutaway skirt (PRD §6), not $strata or $topstyle, which the P2 cached jobs still pair with.
# The station shelter and the bakery use the approved timber-framed cottage of house_cluster ref-1.
skirt="the hexagon side walls show a thin grass lip over dark root-filled topsoil that darkens softly downward into a near-black foot, one continuous dark earth"
toprail="stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun, neutral grey studio background, high camera looking down at about 65 degrees elevation so all six hexagon edges read clearly, the dark earth side walls visible along the front"
rail="single standard-gauge railway track: two steel rails with bright polished running tops fixed to evenly spaced dark timber sleepers, bedded in a low raised bank of grey crushed-stone ballast with neatly sloped shoulders"
cottage="dark oak half-timbering over cream lime-plaster panels, a steep brown clay-tile roof with gables, tall red-brick chimneys with clay pots, and small-paned timber casement windows"
# Trains are recoloured per instance at runtime like cars (PRD §6), so the reference paint is one plain neutral base.
train="a small six-wheeled branch-line steam tank locomotive with a short boiler, a plain round smokebox door with one central handle, a tall chimney, a rounded cab roof and side water tanks, coupled to two short passenger carriages, each with a row of square windows and panelled doors along each side and a gently curved roof, rounded chunky scale-model proportions with realistic detail"
trainpaint="the locomotive cab, boiler cladding and side tanks and both carriage bodies are all painted one plain neutral light grey satin paint, every painted panel smooth and unmarked with no lining, stripes, crests, numbers or lettering anywhere, a blank buffer beam, the smokebox, chimney, frames, buffers and carriage roofs in plain dark charcoal, black spoked wheels, clear window glass"
# Farm animals are GPU-instanced with baked animation (PRD §7.2), so their references ask for simple smooth forms.
animal="smooth sculpted forms like a quality scale model with a bold readable silhouette, the coat reading as broad smooth colour areas with a soft satin sheen"
case "$id" in
  meadow_base) prompts=(
    "A single hexagonal terrain tile, 32 m across, lush meadow grass cap with gentle undulation, sparse wildflowers, visible layered soil strata on the hexagon side walls (topsoil, clay, gravel), $style"
    "Close-up of the meadow grass surface and the soil strata cut face of a hexagonal diorama tile, $style") ;;
  road_straight) prompts=(
    "A single hexagonal diorama tile with a straight two-lane asphalt country road crossing from one flat edge to the opposite flat edge, 6 m wide road, grass shoulders, faded centre line, low curbs, $style"
    "Two identical hexagonal road tiles placed edge to edge with the road continuing seamlessly across the joint, close-up at the seam, $style") ;;
  tree_hero_oak) prompts=(
    "A single hero oak tree for a stylized-real diorama, 12 m tall, broad rounded canopy of leaf clusters, gnarled trunk with root flare, $style"
    "Bark and leaf-cluster material close-up for a stylized-real diorama oak tree, $style") ;;
  road_bends) prompts=(
    "Sharp bend road tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, lush meadow grass cap and $strata, flat-topped so one flat side faces the camera along the bottom of the frame, carrying a $road. Seen from above, the road starts at the middle of the bottom side and turns sharply right to end at the middle of the lower-right side, the neighbouring side that shares the bottom-right corner. The road stays in the bottom-right part of the tile and the rest of the tile is open grass, $topstyle"
    "Wide bend road tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, lush meadow grass cap and $strata, flat-topped so one flat side faces the camera along the bottom of the frame, carrying a $road. Seen from above, the road starts at the middle of the bottom side and curves gently right to end at the middle of the upper-right side. The lower-right side between the two road ends is grass, and the top side opposite the start is grass too, $topstyle"
    "Y junction road tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, lush meadow grass cap and $strata, with a three-way junction of $road. Three road arms meet at the tile centre in a symmetric Y, each arm 120 degrees from the next, leaving through three alternating flat edges (every other edge) square-on at the edge midpoints, with grass on the three edges between the arms. The kerbs curve smoothly between neighbouring arms and the dashed centre lines stop short of the junction. Exactly three arms, $topstyle") ;;
  river) prompts=(
    "Two separate flat-sided hexagonal diorama tiles side by side, each 32 m across with a meadow grass cap and $strata. Left tile: a straight river running from one flat edge across to the opposite flat edge. Right tile: a curved river running from one flat edge to the flat edge two positions away, skipping one edge, a gentle bend. The 8 m wide river channel is sunk below the meadow surface between natural earthy banks with pebbles and reeds, clear water tinted pale turquoise at the margins and teal-blue in the middle, sun glints, soft caustics on the pebbly channel floor. Where the river reaches the tile side wall, $cut, $style"
    "Close-up of a natural river bank on a hexagonal diorama tile: the meadow grass edge, an earthy bank sloping down to the water, pebbles and reeds, clear water tinted pale turquoise at the margins and teal-blue in the middle, sun glints, soft caustics on the pebbly channel floor, and where the channel reaches the tile side wall $cut, $style") ;;
  river_road_bridge) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $strata. A straight 8 m wide river runs between one pair of opposite flat edges in a channel cut below the meadow surface with natural earthy banks, $water. A $road runs straight between another pair of opposite flat edges and crosses the river at 60 degrees on a small single-span stone-faced road bridge with low parapet walls and abutments set into the banks. Where the river meets the tile side wall, $cut, $style"
    "Close-up of a small single-span stone-faced country road bridge on a diorama tile: the asphalt deck with low kerbs and a faded dashed centre line, low stone parapet walls, abutments set into earthy river banks, the river flowing underneath, $water, $style") ;;
  beach) prompts=(
    "A single flat-sided hexagonal coast tile for a diorama, 32 m across. Ocean fills the side with two adjacent flat edges, lush meadow grass fills the two flat edges opposite them, and a curving sand shoreline runs across the tile from one flat edge to the opposite flat edge. Bands from land to sea: meadow grass, dry pale sand, a darker wet-sand band, a lacy white surf foam line, $water. Under the land the side walls show $strata; on the ocean side $cut, with the sand floor sloping down, $style"
    "Close-up of the waterline on a diorama beach tile: dry pale sand, a darker damp-sand band, a thin lacy white surf foam line along the shore, clear turquoise shallows over a rippled sandy floor with caustics, $style") ;;
  ocean) prompts=(
    "A single regular hexagonal deep ocean tile for a diorama with exactly six straight flat edges, 32 m across, on a plain neutral grey studio backdrop. Open temperate sea with layered gentle waves, a few white foam flecks on crests, $water. On every side $cut. Through the clear side walls a pale sandy shelf rises toward one edge and slopes down to a darker sandy seabed with scattered pebbles. Photoreal PBR rendering with plain sand and pebbles only, $style"
    "Close-up at one corner of a hexagonal diorama ocean tile on a plain neutral grey studio backdrop, looking at the 120 degree corner where two side faces of the hexagon meet. The tile is one cast block of clear tinted resin with no container, no glass walls and no rim: the top of each side face follows the wavy water surface exactly, the water column turquoise near the top fading to deep blue lower down, a pale sandy shelf stepping down to a darker sandy seabed with a few pebbles, soft caustic light on the sand, photoreal PBR rendering, $style") ;;
  house_cluster) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $strata, with a cluster of 3 small stylized-real rural houses (pitched clay-tile and slate roofs, rendered plaster and timber walls, chimneys, timber window frames) on a level gravel-and-paving pad, small gardens, low hedges and a picket fence, and a short asphalt driveway that leaves the pad and meets one flat edge of the tile square-on, where it joins a short stub of 6 m wide two-lane asphalt road with low kerbs and a faded dashed centre line, $style"
    "Close-up of one small stylized-real rural house on a diorama tile: weathered clay roof tiles, rendered plaster walls, timber window frames and front door, a chimney, a gravel path, a low hedge and a small garden, $style") ;;
  forest) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, $strata, covered by a dense mixed forest: a few broad rounded oaks among many tall spruce conifers with dark green needle tiers, undergrowth of ferns, shrubs and saplings, a fallen mossy log and leaf litter on the forest floor, $style"
    "Close-up of a stylized-real spruce conifer and the forest undergrowth on a diorama tile: rough flaky bark, layered tiers of needle clusters, ferns, low shrubs, moss and leaf litter at the trunk base, $style") ;;
  meadow_props) prompts=(
    "One corner fragment of a hexagonal meadow diorama tile with $strata, on a plain neutral grey studio backdrop: lush meadow grass with scattered wildflower clumps (white daisies, yellow buttercups, purple clover, blue cornflowers), each clump about 1 m across with small flower heads in natural proportion to the grass, and weathered grey granite rocks from 0.5 m to 2 m with lichen patches, partly sunk into the turf with grass growing around their bases, photoreal PBR materials, $style"
    "Close-up of meadow scatter on a diorama tile on a plain neutral grey studio backdrop: small realistic wildflower heads of white daisies, yellow buttercups, purple clover and blue cornflowers among dense meadow grass, each flower head about the width of a few grass blades, and a weathered lichen-spotted granite rock half sunk into the turf with grass around its base, photoreal PBR materials, $style") ;;
  vehicles) prompts=(
    "A single compact four-door sedan car, about 4.2 m long, a softly rounded three-box shape with a short bonnet, short overhangs, slightly oversized wheels pushed out to the corners, four doors with side windows and a short separate boot, a plain grille of smooth horizontal slats with a blank centre and no emblem, $car, $alone, $style"
    "A single small panel van, about 4.4 m long, a short sloping bonnet and a two-seat cab with windows only in the two front doors, a tall boxy cargo body behind the cab with solid painted side panels, a sliding side door and twin rear doors, $car, $alone, $style"
    "A single compact pickup truck with a single cab, about 4.5 m long with a normal wheelbase and believable real-world proportions, only slightly chunky and never cartoonish, a short bonnet and a two-door cab with one row of seats. Behind the cab sits a clean rectangular open cargo box taking up nearly half the truck's length, empty and uncovered, its flat floor sunk well below the tops of its painted side walls, and a closed upright tailgate at the back, a plain grille of smooth horizontal slats with a blank centre and no emblem, $car, $alone, $style") ;;
  fish) prompts=(
    "A single small ocean school fish about 0.4 m long with $fishbody, coloured with $oceanfish, shown alone floating in mid-air above the plain grey studio floor with a soft shadow below, the whole fish centred in frame and seen exactly side-on in profile with the head to the left, $look"
    "Looking straight down from directly above at open shallow sea water that runs out past every edge of the frame, the clear water tinted pale turquoise over a pale sandy floor with a few scattered pebbles, gentle sun glints on the surface and soft caustic light on the sand. A small school of about twelve small ocean fish swims together just under the surface, all heading the same way toward the top right of the frame in a loose teardrop-shaped group, each fish about 0.4 m long with a streamlined torpedo-shaped body, a clean forked tail fin and small rounded pectoral fins spread to the sides, coloured with $oceanfish, every fish reading as a clear separate dark blue-grey torpedo silhouette with its forked tail, stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun"
    "Two small fish with exactly the same body shape and size swim one above the other in the same direction, both about 0.4 m long with $fishbody, both seen exactly side-on in profile with the head to the left, floating in mid-air in front of the plain grey studio backdrop with soft shadows on the floor below. The upper fish is coloured with $oceanfish. The lower fish is coloured with $riverfish. The picture shows only the two fish on the plain backdrop, $look") ;;
  birds) prompts=(
    "A single $birdbody, gliding with both wings spread and raised in a shallow V and the tail slightly fanned, shown alone floating in mid-air above the plain grey studio floor with a soft shadow below, the whole bird centred in frame and seen in true side profile from the bird's left with the head pointing to the left of the frame and the camera level with the bird, so the body profile and the outline of both raised wings read clearly above the back, $look"
    "A bird's-eye view photographed from directly overhead with the camera pointing straight down at the ground: five small birds fly freely through open air in a loose group, each seen flat from above so its back, both spread upper wings and its fanned tail read as a clear separate cross-shaped silhouette, three gliding with wings spread wide and two with wings raised mid-flap. Each bird is a $birdbody. Far below them lies a flat sunlit map-like landscape of lush meadow grass and the dark green rounded treetops of a forest edge, softly out of focus and running out past every edge of the frame, with small soft bird shadows on the grass, stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun, bright midday light"
    "Three small birds roosting together on a leafy branch in the top of a broad rounded oak tree canopy, each a $birdbody, all three with wings folded neatly against their bodies in a plump rounded resting posture, one facing left, one facing right and one turned toward the camera, $style") ;;
  rail) prompts=(
    "Straight railway tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, lush meadow grass cap and $skirt, flat-topped so one flat side faces the camera along the bottom of the frame, carrying a $rail. Seen from above, the track runs straight from the middle of the bottom side across the centre of the tile to the middle of the top side, meeting both sides square-on, and the rest of the tile is open meadow grass, $toprail"
    "Gentle curve railway tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, lush meadow grass cap and $skirt, flat-topped so one flat side faces the camera along the bottom of the frame, carrying a $rail. Seen from above, the track starts at the middle of the bottom side and curves gently right in one smooth wide arc to end at the middle of the upper-right side. The lower-right side between the two track ends is grass, and the top side opposite the start is grass too, $toprail"
    "A single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $skirt. A $rail runs straight between one pair of opposite flat edges, and a $road runs straight between another pair of opposite flat edges and crosses the railway at 60 degrees on a level crossing, where the asphalt runs flush up to the rails over smooth timber crossing boards laid between them. Four plain white-painted timber field gates on stout white posts stand at the road edges, two on each side of the railway, swung open parallel to the track. The only things at the crossing are the gates and their posts, $style") ;;
  rail_station) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $skirt. A $rail runs straight between two opposite flat edges. Alongside the track sits a short raised country platform about 20 m long with a stone-flag surface, a pale stone edge and a sloping ramp at each end. On it stands a small open-fronted waiting shelter with low red-brick walls below $cottage, its roof sweeping forward into a deep timber canopy over the platform on carved timber brackets, with a slatted timber bench under the canopy, one black cast-iron lamp post, two flower tubs and a white picket fence along the back of the platform. The only things on the platform are the shelter, the bench, the lamp post and the flower tubs, $style"
    "Close-up of a small country railway waiting shelter on a short platform beside a $rail: low red-brick walls below $cottage, its roof sweeping forward into a deep timber canopy on carved timber brackets, a slatted timber bench under the canopy, one black cast-iron lamp post, a stone-flag platform with a pale stone edge and one flower tub. The only things on the platform are the shelter, the bench, the lamp post and the flower tub, $style") ;;
  train) prompts=(
    "A short passenger train made of $train, and $trainpaint. The train stands on a short straight length of track with timber sleepers on grey ballast laid on the plain grey studio floor with a soft contact shadow, the whole train centred in frame and seen from the front-left with the locomotive nearest the camera, $style"
    "An exact side elevation of a short passenger train made of $train, and $trainpaint. The camera looks at the middle of the train at a perfect right angle to the track from far away through a long telephoto lens, level with the wheel axles, so the train reads as a flat side elevation with no front or end faces visible, the locomotive at the left facing left, and the near rail running as one straight horizontal line across the frame. The train stands on a short straight length of track with timber sleepers on grey ballast on the plain grey studio floor, the whole train filling the width of the frame, $look") ;;
  farm) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $skirt, laid out as a small farmyard. About half the tile is a field of neat parallel ploughed furrows of dark brown earth beside a few rows of young green crops. The other half holds a red-painted vertical-board timber barn with a steep dark slate roof and large double doors, a packed-earth yard with a few round hay bales and a small stack of rectangular hay bales, and a grassy paddock enclosed by a weathered post-and-rail timber fence, $style"
    "Close-up of a farmyard corner on a diorama tile: a red-painted vertical-board timber barn with a steep dark slate roof and open large double doors, a weathered post-and-rail timber fence, round and rectangular hay bales on a packed-earth yard scattered with loose straw, and the edge of a field of neat ploughed furrows, $style") ;;
  farm_animals) prompts=(
    "A single black-and-white dairy cow about 1.5 m tall at the shoulder, with a sturdy rectangular body on four straight legs, a broad rounded head with small ears and a pale grey muzzle, a thin tail ending in a dark tuft, and bold irregular black and white patches, $animal, standing alone on the plain grey studio floor with a soft contact shadow, the whole animal centred in frame and seen exactly side-on in profile with the head to the left and the camera level with the animal, $look"
    "A single adult sheep with a plump rounded body of thick creamy-white wool fleece, a black face, black legs, small dark ears and a short tail, $animal, standing alone on the plain grey studio floor with a soft contact shadow, the whole animal centred in frame and seen exactly side-on in profile with the head to the left and the camera level with the animal. The picture shows only the sheep on the plain backdrop, $look"
    "A bird's-eye view photographed from directly overhead with the camera pointing straight down at the ground: a small herd of four black-and-white dairy cows and a flock of six sheep with creamy-white fleeces and black faces graze on a flat sunlit map-like meadow of lush green grass, in two loose separate groups, each animal seen flat from above so its back, head and ears read as a clear separate silhouette, with small soft shadows on the grass. The meadow runs out past every edge of the frame, $animal, stylized-real diorama miniature, real PBR materials, slightly exaggerated proportions, soft noon sun, bright midday light") ;;
  windmill) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, $skirt, its lush meadow grass cap rising into a low rounded grassy mound in the middle, crowned by a traditional English tower windmill about 18 m tall: a gently tapering round tower of black-tarred brick with small white-framed windows and a timber door at its foot, a white boat-shaped timber cap, four large white sails in an X made of open timber lattice frames with shutters, and a small eight-bladed fantail wheel on a frame at the back of the cap. A gravel path winds up the mound to the door, $style"
    "Close-up of the top of a traditional English tower windmill: the black-tarred brick tower top, a white boat-shaped timber cap with a gallery rail, the hub where four large white sails meet, each sail an open timber lattice frame with rows of shutters, and a small eight-bladed white fantail wheel on a frame behind the cap, $style"
    "A single flat-sided hexagonal diorama tile, 32 m across, $skirt. The whole lush meadow grass cap swells up into one broad smooth grassy hill that rises from the tile edges to a rounded top about 4 m higher in the middle, like an upturned saucer, and a traditional English tower windmill about 18 m tall stands on the very top of the hill: a gently tapering round tower of black-tarred brick with small white-framed windows and a timber door at its foot, a white boat-shaped timber cap, four large white sails in an X made of open timber lattice frames with shutters, and a small eight-bladed fantail wheel on a frame at the back of the cap. A gravel path climbs the slope of the hill to the door, $style") ;;
  bakery) prompts=(
    "A single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $skirt, with one small two-storey village cottage shop in the timber-framed English cottage style: $cottage. Its ground-floor front is a wide small-paned timber bow window full of crusty loaves, round cobs, plaited loaves and buns on wooden shelves and in wicker baskets, beside a half-glazed timber shop door under a small clay-tile canopy, with a wicker basket of bread on a bench by the door and flower boxes under the upper windows. The beam above the bow window is plain dark oak like the rest of the framing. The building stands on a flagstone forecourt that meets one flat edge of the tile square-on, where it joins a short stub of $road, $style"
    "Close-up of the front of a small timber-framed English village cottage shop: $cottage, a wide small-paned timber bow window full of crusty loaves, round cobs, plaited loaves and buns on wooden shelves and in wicker baskets, a half-glazed timber door under a small clay-tile canopy, a wicker basket of bread on a bench by the door and flagstone paving. The beam above the bow window is plain dark oak like the rest of the framing, $style") ;;
  # River ends use the approved beach and river looks with the O4 skirt. The mouth widens to about 10 m
  # over the sand as in the approved water look-dev (docs/kit/water-contract.md, Width evidence).
  river_mouth) prompts=(
    "River mouth coast tile: a single flat-sided hexagonal coast tile for a diorama, 32 m across. Ocean fills the side with two adjacent flat edges, lush meadow grass fills the two flat edges opposite them, and a straight sand shoreline runs across the tile from one flat edge to the opposite flat edge. Bands from land to sea: meadow grass, dry pale sand, a darker damp-sand band, a lacy white surf foam line, $water. An 8 m wide river runs in from the middle of one grass edge in a channel sunk below the meadow surface between natural earthy banks with pebbles and reeds, and flows straight across the tile toward the sea. Where it reaches the sand the banks fall away and the river opens out to about 10 m wide in a shallow fan of clear rippled water over the sand and runs out into the surf. Under the grass $skirt; where the river and the ocean reach the tile side wall, $cut, with the sand floor sloping down, $style"
    "River mouth coast tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, flat-topped so one flat side faces the camera along the bottom of the frame. Seen from above, ocean fills the top side and the upper-right side, lush meadow grass fills the bottom side and the lower-left side, and a straight sand beach runs diagonally across the middle of the tile from the middle of the upper-left side to the middle of the lower-right side, with bands from land to sea: meadow grass, dry pale sand, a darker damp-sand band, a lacy white surf foam line, $water. An 8 m wide river runs in square-on at the middle of the bottom side, in a channel sunk below the meadow surface between natural earthy banks, and flows straight up the tile. Where it crosses the sand in the middle of the tile it opens out to about 10 m wide in a shallow fan over the sand and flows out into the sea toward the top side. Under the grass $skirt, and where the river reaches the bottom side wall, $cut, $toprail"
    "Close-up of the river mouth on a diorama beach tile: a small clear river runs from between grassy earthy banks across pale sand, opening out into a broad shallow stream of rippled water over the sandy floor, and runs into the sea at a lacy white surf foam line, with a darker damp-sand band along both sides of the stream and clear turquoise shallows over a rippled sandy floor with caustics, $style") ;;
  river_spring) prompts=(
    "Spring tile: a single flat-sided hexagonal diorama tile, 32 m across, lush meadow grass cap and $skirt. Near the middle of the tile a small round spring pool about 12 m across sits in a shallow grassy hollow, ringed by weathered grey rocks, tussocks of reeds and rushes and a few water plants, $water, a pale pebbly floor showing through the water and a gentle ring of ripples where the spring wells up. An 8 m wide river runs out of the pool to the middle of one flat edge of the tile in a channel sunk below the meadow surface between natural earthy banks with pebbles and reeds. Where the river reaches the tile side wall, $cut. The rest of the tile is open meadow grass, $style"
    "Spring tile: a single regular hexagonal diorama tile with exactly six straight flat edges, centred in frame, 32 m across, lush meadow grass cap and $skirt, flat-topped so one flat side faces the camera along the bottom of the frame. Seen from above, a small round clear spring pool about 12 m across sits in the middle of the tile, ringed by grey rocks and reeds, and an 8 m wide river runs out of the pool straight down to the middle of the bottom side, meeting it square-on, in a channel sunk below the meadow surface between natural earthy banks, $water. Where the river reaches the bottom side wall, $cut. The other five sides are open meadow grass, $toprail"
    "Close-up of a small spring pool on a hexagonal diorama tile: clear water welling up over a pale pebbly floor with a gentle ring of ripples on the surface, $water, ringed by weathered lichen-spotted grey rocks, tussocks of reeds and rushes and lush meadow grass, and the start of a small stream flowing out of the pool between natural earthy banks with pebbles, $style") ;;
